        for color in colors:
            for a, b in edges[color]:
                if (a, b) == (ui, vi) or (b, a) == (ui, vi):
                    visited.add(color)
                    break

        while queue:
            u = queue.popleft()
            for v, color in edges[color]:
                if v not in visited and (u, v) not in visited:
                    visited.add((u, v))
                    queue.append(v)

